import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long a = nextLong(), b = nextLong(), budget = nextLong();
        // Fewest skips to make the last shipment yours: remainder r in 1..a+b needs (r-1)/a skips.
        long[] cost = new long[n];
        for (int i = 0; i < n; i++) cost[i] = ((nextLong() - 1) % (a + b)) / a;
        Arrays.sort(cost);
        long answer = 0;
        for (long c : cost) {
            if (c > budget) break;
            budget -= c;
            answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n, a, b, budget := readInt(), readInt(), readInt(), readInt()
	// Fewest skips to make the last shipment yours: remainder r in 1..a+b needs (r-1)/a skips.
	cost := make([]int, n)
	for i := range cost {
		cost[i] = ((readInt() - 1) % (a + b)) / a
	}
	sort.Ints(cost)
	answer := 0
	for _, c := range cost {
		if c > budget {
			break
		}
		budget -= c
		answer++
	}
	fmt.Println(answer)
}
